kernel_witness_check.proof_type:
let z := fun g h p => c' g h (↑p).1 * (c g h (↑p).2)⁻¹;
(∀ (g : Γ) (p : ↑O), z 1 g p = 1 ∧ z g 1 p = 1) ∧
  (∀ (g h k : Γ) (p : ↑O),
      c' h k ((ρ' g)⁻¹ (↑p).1) * (c h k ((ρ g)⁻¹ (↑p).2))⁻¹ * (z (g * h) k p)⁻¹ * z g (h * k) p * (z g h p)⁻¹ = 1) ∧
    ∀ (x : Γ → Fin n → ℂˣ) (x' : Γ → Fin n' → ℂˣ),
      (∀ (i : Fin n), x 1 i = 1) →
        (∀ (i' : Fin n'), x' 1 i' = 1) →
          let δx := fun g h i => x h ((ρ g)⁻¹ i) * (x (g * h) i)⁻¹ * x g i;
          let δx' := fun g h i' => x' h ((ρ' g)⁻¹ i') * (x' (g * h) i')⁻¹ * x' g i';
          let y := fun g p => x' g (↑p).1 * (x g (↑p).2)⁻¹;
          ∀ (g h : Γ) (p : ↑O),
            c' g h (↑p).1 * δx' g h (↑p).1 * (c g h (↑p).2 * δx g h (↑p).2)⁻¹ =
              z g h p * (x' h ((ρ' g)⁻¹ (↑p).1) * (x h ((ρ g)⁻¹ (↑p).2))⁻¹ * (y (g * h) p)⁻¹ * y g p)
